// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testFuzz_property(address caller, address recipient) public {
        vm.assume(caller != c.owner());
        vm.deal(address(c), 1 ether);
        uint256 balanceBefore = address(c).balance;
        vm.prank(caller);
        try c.withdrawAll(recipient) {} catch {}
        assertTrue(address(c).balance == balanceBefore);
    }
}
